sir 0.3

software CourseAdmin {
  metadata {
    displayName "Course Admin";
    namespace "com.example.courseadmin";
  }

  target {
    language java 21;
    framework spring_boot;
    persistence mybatis_plus;
    database mysql;
    build maven;
    interface rest;
  }

  sources { }
  imports { }
  declarations {
    entity Course persistent {
      identity id: Id generated auto;
      field code: Code;
      field name: Name;
      field description: Optional<Remark>;
      field capacity: Quantity;
      field version: Version;
    }
    view CourseDetail from Course {
      field id: Id;
      field code: Text;
      field name: Text;
      field description: Optional<Text>;
      field capacity: Count;
      field version: Serial;
    }
    input GetCourseInput {
      field id: Id;
    }
    input CreateCourseInput {
      field code: Code;
      field name: Name;
      field description: Optional<Remark>;
      field capacity: Quantity;
    }
    input UpdateCourseInput patch of Course {
      field id: Id;
      field expectedVersion: Version;
      field changes: UpdateCourseChanges;
    }
    input UpdateCourseChanges {
      field name: Optional<Name>;
      field description: Optional<Remark>;
      field capacity: Optional<Quantity>;
    }
    error CourseNotFound http 404;
    error EmptyChange http 400;
    error StaleVersion http 409;
    capability GetCourse {
      input GetCourseInput;
      output CourseDetail;
      fails CourseNotFound;
      requires readonly;
      expose query;
      workflow {
        load Course by input.id as course else CourseNotFound;
        return course;
      }
    }
    capability CreateCourse {
      input CreateCourseInput;
      output CourseDetail;
      requires atomic;
      expose command;
      workflow {
        create Course as created {
          code: input.code;
          name: input.name;
          description: input.description;
          capacity: input.capacity;
        }
        persist created;
        return created;
      }
    }
    capability UpdateCourse {
      input UpdateCourseInput;
      output CourseDetail;
      fails CourseNotFound;
      fails EmptyChange;
      fails StaleVersion;
      requires atomic;
      expose command;
      workflow {
        load Course by input.id as course for update else CourseNotFound;
        validate input.changes.name is present or input.changes.description is present or input.changes.capacity is present else EmptyChange;
        validate course.version == input.expectedVersion else StaleVersion;
        update course when course.version == input.expectedVersion else StaleVersion {
          name: max(input.changes.name, course.name);
          description: input.changes.description;
          capacity: max(input.changes.capacity, course.capacity);
          version: course.version + 1;
        }
        persist course;
        return course;
      }
    }
  }
}
